using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Localization;using UnityEngine.Localization.Settings;using TMPro;using Object=UnityEngine.Object;
public static class UiInventoryCycle07 {
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;
 public static object LocaleBaseline(){const string path="outputs/chapter45-detailed-design-2026-10-03/ui-cycle07/original-locale.json";if(File.Exists(path))throw new Exception("Original locale already captured");var locale=LocalizationSettings.SelectedLocale;var locales=LocalizationSettings.AvailableLocales.Locales.Select(l=>new{code=l.Identifier.Code,name=l.name,path=AssetDatabase.GetAssetPath(l)}).ToArray();var result=new{selected=locale==null?null:locale.Identifier.Code,selectedAsset=AssetDatabase.GetAssetPath(locale),available=locales,projectLocale=LocalizationSettings.ProjectLocale?.Identifier.Code};File.WriteAllText(path,Json(result));return result;}
 public static object Capture(string filename){if(System.IO.Path.GetFileName(filename)!=filename)throw new Exception("Basename required");string file="outputs/chapter45-detailed-design-2026-10-03/ui-cycle07/"+filename;if(File.Exists(file))throw new Exception("Preserve evidence");var d=Object.FindFirstObjectByType<Chapter45Director>();var texts=Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(t=>t.gameObject.scene==d.gameObject.scene).Select(t=>new{path=PathOf(t.transform),t.text,active=t.gameObject.activeInHierarchy,t.enabled,font=AssetDatabase.GetAssetPath(t.font),fontSize=t.fontSize,autoSize=t.enableAutoSizing,overflow=t.overflowMode.ToString(),canvas=t.GetComponentInParent<Canvas>()!=null,rect=t.rectTransform.rect.ToString()}).ToArray();var result=new{scene=d.gameObject.scene.name,locale=LocalizationSettings.SelectedLocale?.Identifier.Code,texts,choices=d.choices.Select(c=>new{c.name,c.kind,c.leftName,c.rightName,c.riskDescription,c.Description}).ToArray(),floors=d.route.segments.GroupBy(s=>s.floor).Select(g=>new{floor=g.Key,labels=g.Select(s=>s.label).Distinct().ToArray()}).ToArray(),lifts=d.lifts.Select(l=>new{l.name,l.destinationLabel,l.afterSegment,l.destinationSegment}).ToArray(),hazards=d.hazards.Select(h=>new{h.name,h.warning}).ToArray(),roles=Object.FindObjectsByType<Chapter45RoleAction>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(a=>a.gameObject.scene==d.gameObject.scene).Select(a=>new{path=PathOf(a.transform),a.role,a.warningText,active=a.gameObject.activeInHierarchy}).ToArray()};File.WriteAllText(file,Json(result));return new{file,scene=d.gameObject.scene.name,textCount=texts.Length,activeTexts=texts.Count(t=>t.active)};}
}
